// AE-03 Worker A: Data Ingestion & Entity Extraction
// Receives: { raw_text, url, extract_entities }
// Returns: DataWorkerResult (Pydantic-compliant)

const input = $input.first().json;
const rawText = input.raw_text || '';
const url = input.url || null;
const entityTypes = input.extract_entities || ['api_endpoints', 'schemas', 'technologies'];

// --- Simulated entity extraction logic ---
const entities = {};
for (const entityType of entityTypes) {
  if (entityType === 'api_endpoints') {
    const endpoints = rawText.match(/\/api\/[\w\/]+/g) || [];
    entities[entityType] = endpoints.length > 0 ? endpoints : ['/api/v1/default'];
  } else if (entityType === 'schemas') {
    entities[entityType] = ['EntitySchema', 'ResponseSchema'];
  } else if (entityType === 'technologies') {
    entities[entityType] = ['REST', 'JSON', 'OAuth2'];
  } else {
    entities[entityType] = [];
  }
}

const summary = `Extracted ${Object.keys(entities).length} entity categories from input (${rawText.length} chars).`;

return [{
  json: {
    status: 'success',
    entities: entities,
    summary: summary,
    raw_data: {
      input_length: rawText.length,
      url_provided: url !== null,
      entity_types_requested: entityTypes
    }
  }
}];
